(* [comment removed for export] *)
Definition LOCHIP (m : word -> option byte) (s shift wpl h : Z) : word -> option byte :=
  wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes m
    (Z_to_bv 64 (s - 168)) (word_to_le_bytes 8 (Z_to_bv 64 (- shift))))
