  (* [comment removed for export] *)
  Lemma hip_R2 : forall regs m (s data wpl shift i : Z),
    (224 <= s)%Z -> (s < 2 ^ 64)%Z -> (2 <= wpl < 2 ^ 25)%Z -> (1 <= shift <= 31)%Z -> (0 <= i < 2 ^ 31)%Z ->
    rdn SEGS m (Z_to_bv 64 (s - 120)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 (4 * wpl))) ->
    rdn SEGS m (Z_to_bv 64 (s - 208)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 (0 - hipA5 wpl - 4))) ->
    getr regs 2 = Z_to_bv 64 (s - 224) -> getr regs 22 = Z_to_bv 64 i -> getr regs 13 = Z_to_bv 64 wpl -> getr regs 26 = Z_to_bv 64 data ->
    getr regs 20 = Z_to_bv 64 shift -> getr regs 21 = Z_to_bv 64 (4 * wpl) -> getr regs 25 = Z_to_bv 64 i -> getr regs 24 = Z_to_bv 64 (4 * wpl) ->
    getr regs 27 = Z_to_bv 64 shift -> getr regs 6 = Z_to_bv 64 wpl -> getr regs 8 = Z_to_bv 64 (data + 4 * wpl * i) ->
    exists regs',
      msteps SEGS (mkst regs (0x7cd0c : word) m rom) (mkst regs' (0x7cd4c : word) m rom)
      /\ getr regs' 10 = Z_to_bv 64 (data + 4 * wpl * i - 4 * (wpl - 1)) /\ getr regs' 11 = Z_to_bv 64 (data + 4 * wpl * i)
      /\ regs_agree (fun r => In r [10; 11; 12; 14]%list) regs regs'.
Proof.
