  (* [comment removed for export] *)
  Lemma hip_I : forall (last : bool) regs m (line wpl k : Z) (bs5 bs2 : list byte) (v5 v2 : word),
    (2 <= wpl < 2 ^ 25)%Z -> (0 <= k)%Z -> (if last then k = wpl - 2 else k < wpl - 2)%Z -> (0 <= line)%Z -> (line + 4 * wpl < 2 ^ 62)%Z ->
    rdn SEGS m (Z_to_bv 64 (line + 4 * (wpl - 2 - k))) 4 = Some bs5 -> bytes_le_to_Z bs5 = bv_unsigned v5 ->
    rdn SEGS m (Z_to_bv 64 (line + 4 * (wpl - 1 - k))) 4 = Some bs2 -> bytes_le_to_Z bs2 = bv_unsigned v2 ->
    store_ok SEGS m (Z_to_bv 64 (line + 4 * (wpl - 1 - k))) 4 = true ->
    getr regs 11 = Z_to_bv 64 (line - 4 * k) -> getr regs 10 = Z_to_bv 64 (line - 4 * (wpl - 1)) -> getr regs 24 = Z_to_bv 64 (4 * wpl) ->
    getr regs 19 = Z_to_bv 64 (4 * wpl - 4) ->
    exists regs' (wv : word),
      msteps SEGS (mkst regs (0x7cd4c : word) m rom)
                  (mkst regs' (if last then (0x7ce4c : word) else (0x7cd4c : word)) (wbytes m (Z_to_bv 64 (line + 4 * (wpl - 1 - k))) (word_to_le_bytes 4 wv)) rom)
      /\ (if last then getr regs' 10 = Z_to_bv 64 line /\ getr regs' 11 = Z_to_bv 64 line
          else getr regs' 11 = Z_to_bv 64 (line - 4 * (k + 1)) /\ getr regs' 10 = Z_to_bv 64 (line - 4 * (wpl - 1)))
