  (* [comment removed for export] *)
  Lemma hip_F : forall (last : bool) regs m (s data wpl shift i h line : Z) (bs0 bsm : list byte) (v0 vm : word),
    (224 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= wpl < 2 ^ 25)%Z -> (1 <= shift <= 31)%Z -> (0 <= i)%Z -> (if last then i + 1 = h else i + 1 < h)%Z -> (h < 2 ^ 31)%Z ->
    (line = data + 4 * wpl * i)%Z -> (0 <= line)%Z -> (line + 4 * wpl <= s - 224)%Z ->
    rdn SEGS m (Z_to_bv 64 line) 4 = Some bs0 -> bytes_le_to_Z bs0 = bv_unsigned v0 ->
    rdn SEGS m (Z_to_bv 64 (s - 152)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 (0x1f424 + 4 * shift))) ->
    rdn SEGS m (Z_to_bv 64 (0x1f424 + 4 * shift)) 4 = Some bsm -> bytes_le_to_Z bsm = bv_unsigned vm ->
    rdn SEGS m (Z_to_bv 64 (s - 112)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 h)) ->
    store_ok SEGS m (Z_to_bv 64 line) 4 = true ->
    getr regs 2 = Z_to_bv 64 (s - 224) -> getr regs 10 = Z_to_bv 64 line -> getr regs 11 = Z_to_bv 64 line -> getr regs 27 = Z_to_bv 64 shift ->
    getr regs 20 = Z_to_bv 64 shift -> getr regs 22 = Z_to_bv 64 i -> getr regs 25 = Z_to_bv 64 i -> getr regs 8 = Z_to_bv 64 line ->
    getr regs 21 = Z_to_bv 64 (4 * wpl) -> getr regs 9 = Z_to_bv 64 (line + 4 * wpl) ->
    exists regs' (wv : word),
      msteps SEGS (mkst regs (0x7ce4c : word) m rom)
                  (mkst regs' (if last then (0x7cebc : word) else (0x7cd0c : word)) (wbytes m (Z_to_bv 64 line) (word_to_le_bytes 4 wv)) rom)
      /\ getr regs' 22 = Z_to_bv 64 (i + 1) /\ getr regs' 25 = Z_to_bv 64 (i + 1) /\ getr regs' 8 = Z_to_bv 64 (line + 4 * wpl)
      /\ getr regs' 9 = Z_to_bv 64 (line + 4 * wpl + 4 * wpl)
